INSERT INTO `5kcrm_customer_ledger` VALUES (12, 11, 0, 64, 1, 1, 31, 'IPAD修改安全核查流程', '签名要求\n安全核查每一个步骤均需签名：\n手术医生 1 人\n麻醉医生 1 人\n手术护士 2 个签名位（可只签 1 人）\n身份验证方式\n第一个核查步骤：输入工号 + 密码验证\n后续步骤：自动带入工号，仅输入密码确认\n电脑端展示\n电脑端新增安全核查单页面\n展示内容与 iPad 端同步，仅用于查看与追溯', '王兰平', '新增需求', '已完成', 1769742457, 1769742457, 1773719319, 3, 2, '', 1769742640, 1773719319);
