INSERT INTO `5kcrm_customer_ledger` VALUES (38, 79, 0, 52, 0, 0, 0, 'IPAD端患者交接麻醉方式修改', '<p class=\"MsoNormal\"><span>交接单麻醉方式：局麻改为局部浸润麻醉</span></p>', '张远忠', '功能完善', '已完成', 1770084921, 0, 1772435892, 3, 5, '', 1770085016, 1772435892);
INSERT INTO `5kcrm_customer_ledger` VALUES (39, 79, 0, 52, 0, 0, 0, '电脑端术前术后方式修改', '<p class=\"MsoNormal\"><span><span>术前访视、术后随访，电脑端与</span><span>pad</span><span>端不一致。需要改成与</span><span>pad</span><span>一致。如：</span></span></p>\n<p class=\"MsoNormal\"><span><span>术前访视电脑端：传染病项目</span><span>:</span><span>正常、不正常；签字确认无签字人关系</span></span></p>\n<p class=\"MsoNormal\"><span>术后随访电脑端：特殊意见、签字确认</span></p>', '张远忠', '其他问题', '已完成', 1770085025, 0, 1772435905, 3, 5, '', 1770085125, 1772435905);
