INSERT INTO `5kcrm_customer_ledger` VALUES (42, 3, 0, 41, 1, 1, 11, '行为管理系统鞋柜提升周转率刷卡规则修改', '<p>鞋橱刷卡存放后再次刷卡基本都是取出，所以现将鞋橱规则进行修改:刷卡鞋橱固定信息后10分钟内可多次刷卡，超过十分钟后再次刷卡视为拿取，并在半小时后清除信息，以提升鞋柜周转率</p>', '张婷', '新增需求', '待处理', 1770098781, 0, 0, 26, 5, '', 1770098926, 1770098926);
