INSERT INTO `5kcrm_customer_ledger` VALUES (44, 79, 0, 52, 1, 3, 12, '消毒供应追溯系统对接问题', '<p>当调用消毒接口使用消毒包失败时，如何能让护理人员及时获取到问题提示？</p>\n<p>已答复：</p>\n<p>1、信息查询的调用，调用失败 ipad没有器械包显示，护士会自己发现 重新扫&nbsp;</p>\n<p>2、查询后的回传失败（不提示护士），系统会进入队列执行，失败后会根据原因重试（断网接口未响应），其他问题会有回传台账（台账时兜底），需要定期查看。</p>\n<p>以上的前提是建立在刚查询的时候没有患者使用信息</p>', '刘兴民', '新增需求', '已关闭', 1770103511, 0, 0, 3, 3, '', 1770103575, 1779692749);
