INSERT INTO `5kcrm_customer_ledger` VALUES (59, 79, 0, 52, 0, 0, 0, '麻醉排班人员安排错误', '<p>根据临床反馈，发现一个问题：麻醉医师，规培人员，若是选他自己当麻醉师的时候，是他本人的名字，若：选了一个本院的麻醉医师，再选他的时候，就成了别人的名字。如：所衍君，若做为第二麻醉医师时，出来的名字是柳启艳，我把柳启艳删掉，再排的时候成了刘艳君，而刘艳君也是规培人员</p>', '张远忠', '使用指导', '处理中', 1770256845, 0, 0, 3, 3, '', 1770256895, 1770256916);
