INSERT INTO `5kcrm_customer_ledger` VALUES (355, 11, 0, 64, 1, 2, 55, '安全核查，增加签名调整需要增加签名人数', '<p>签名数量：三步最多12次签名，每步最多4个(医生、麻醉、巡回、洗手)。<br />签名步骤独立：三个核查步骤的签名互不关联，需分别操作，安全核查单页面展示内容与iPad端同步。<br />独立性：第一步增加的签名，不会自动同步到第二步和第三步；每个步骤需要单独完成签名。</p>', '张连香', '新增需求', '已完成', 1775037122, 1775037122, 1775901699, 2, 2, '', 1775037181, 1775901699);
INSERT INTO `5kcrm_customer_ledger` VALUES (356, 131, 0, 34, 1, 3, 56, '已完成的手术修改增加限制', '<p>已完成的手术目前比较容易被误修改 如以下场景</p>\n<p>1、手术安排人员在电脑端点掉就等于删除，手术结束后无人确认，容易出现疏漏</p>\n<p>2、已完成的安全核查单和器械清点，在返回后进入某一步骤，未保存提示2/3 或 2/5 ，疑是未完成，导致数据统计不精确。</p>', '曹阳', '新增需求', '已完成', 1775117590, 1775117590, 1785496153, 3, 5, '', 1775117753, 1785496153);
INSERT INTO `5kcrm_customer_ledger` VALUES (357, 131, 0, 34, 1, 3, 57, '院感系统需要用药数据', '<p>信息科王志锐老师说医院新上系统，院感需要手术护理的用药执行的数据，但院感还未整理完成，到时候需要配合。</p>', '王志锐', '新增需求', '已关闭', 1775117760, 1775117760, 0, 3, 3, '', 1775117858, 1782098237);
