INSERT INTO `5kcrm_customer_ledger` VALUES (451, 11, 0, 64, 0, 0, 0, '设备送修记录单', '<h1>设备送修记录新增需求功能</h1>\n<p>1、增加送修记录</p>\n<p>必填字段：日期、物品名称、物品编码、故障描述、送修人</p>\n<p>物品编码需要手动输入、用来区分相同设备的送修情况，错输相当于两个物品送修，影响搜索筛选结果</p>\n<ul>\n<li>增加送回记录</li>\n</ul>\n<p>选中送修记录列表的送回按钮进行送回</p>\n<p>必填字段：日期、物品编码、接收人</p>\n<ul>\n<li>筛选</li>\n</ul>\n<p>按照物品编码筛选、物品名称筛选、送修人筛选</p>\n<ul>\n<li>修改、删除</li>\n</ul>\n<p>对填写的内容进行修改和删除</p>', '杨文欣', '新增需求', '已完成', 1777443627, 1777443627, 1779324723, 2, 2, '', 1777443654, 1779324738);
