INSERT INTO `5kcrm_customer_ledger` VALUES (510, 131, 0, 34, 1, 1, 68, '手术闭环提供视图', '<p>2、手术排班时间(护理) &nbsp;&nbsp;&nbsp;3、入手术室时间(护理) &nbsp;&nbsp;&nbsp;&nbsp;4、术前器械清点(护理)&nbsp;&nbsp;6、麻醉开始前核查(护理)&nbsp; &nbsp;&nbsp;8、手术开始前核查(护理)&nbsp;&nbsp;10、关闭体腔前器械清点(护理) &nbsp;&nbsp;11、关闭体腔后器械清点(护理) &nbsp;&nbsp;12、缝合皮肤后器械清点(护理) &nbsp;13、患者离开手术室前核查(护理) &nbsp;&nbsp;操作人，操作人工号，操作时间</p>\n<p>&nbsp;</p>\n\n\n\nPATIENT_ID\n患者 ID\n\n\nVISIT_ID\n就诊 ID\n\n\nOPR_NO\n手术申请单号\n\n\nOPR_PLAN_NAME\n手术排班操作人姓名\n\n\nOPR_PLAN_NO\n手术排班操作人编码\n\n\nOPR_PLAN_TIME\n手术排班操作时间\n\n\nPRE_INSTR_NAME\n术前器械清点操作人姓名\n\n\nPRE_INSTR_NO\n术前器械清点操作人编码\n\n\nPRE_INSTR_TIME\n术前器械清点操作时间\n\n\nANE_CHECK_NAME\n麻醉开始前核查操作人姓名\n\n\nANE_CHECK_NO\n麻醉开始前核查操作人编码\n\n\nANE_CHECK_TIME\n麻醉开始前核查操作时间\n\n\nOPR_CHECK_NAME\n手术开始前核查操作人姓名\n\n\nOPR_CHECK_NO\n手术开始前核查操作人编码\n\n\nOPR_CHECK_TIME\n手术开始前核查操作时间\n\n\nBODY_PRE_NAME\n关闭体腔前器械清点操作人姓名\n\n\nBODY_PRE_NO\n关闭体腔前器械清点操作人编码\n\n\nBODY_PRE_TIME\n关闭体腔前器械清点操作时间\n\n\nBODY_POST_NAME\n关闭体腔后器械清点操作人姓名\n\n\nBODY_POST_NO\n关闭体腔后器械清点操作人编码\n\n\nBODY_POST_TIME\n关闭体腔后器械清点操作时间\n\n\nSKIN_END_NAME\n缝合皮肤后器械清点操作人姓名\n\n\nSKIN_END_NO\n缝合皮肤后器械清点操作人编码\n\n\nSKIN_END_TIME\n缝合皮肤后器械清点操作时间\n\n\nLEAVE_CHECK_NAME\n患者离开手术室前核查操作人姓名\n\n\nLEAVE_CHECK_NO\n患者离开手术室前核查操作人编码\n\n\nLEAVE_CHECK_TIME\n患者离开手术室前核查操作时间\n\n\n', '谈颂子', '新增需求', '已完成', 1779268420, 1779268420, 1779342963, 3, 5, '', 1779268717, 1779342963);
