INSERT INTO `5kcrm_customer_ledger` VALUES (531, 142, 0, 70, 0, 0, 0, '柔灵肌电手环新增开发任务', '<div data-page-id=\"MzANdWd32oPIQoxcLtBczZSXnCc\" data-lark-html-role=\"root\" data-docx-has-block-data=\"false\">\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnv6ROgnk8lar0RRMKlgzIQc\">1、开始采集前，软件需要录入或选择以下信息：</div>\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnZqdwFpuBaZQg3u7MYJswph\">&bull; 被试编号；&bull; 年龄&bull; 性别&bull; 采集日期；&bull; 采集人员；&bull; 设备编号；&bull; 采集手是左手还是右手；&bull; 被试是否惯用右手；&bull; 本次采集任务名称；&bull; 备注信息。信息为txt 以日期+姓名存放文件夹内</div>\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnZqdwFpuBaZQg3u7MYJswph\">2、底部标签的时间无法设置</div>\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnZqdwFpuBaZQg3u7MYJswph\">3、配置文件中修改动作名称后无法读取&nbsp; ，动作标识未排序&nbsp;&nbsp;</div>\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnZqdwFpuBaZQg3u7MYJswph\">4、录制中无法开始下一轮、或跳过本轮</div>\n<div class=\"ace-line text-indent ace-line old-record-id-doxcnZqdwFpuBaZQg3u7MYJswph\">5、录制过程中，视频采集窗口未固定大小</div>\n</div>', '张新闻', '新增需求', '已完成', 1779673792, 1779673792, 1782096573, 3, 5, '', 1779674258, 1782096573);
