INSERT INTO `5kcrm_customer_ledger` VALUES (536, 3, 0, 61, 0, 0, 0, '示教室大屏无画面', '<p>郭娜反映示教室大屏无画面，原因是电脑问题，更换电脑后正常；同时按照要求将两个屏幕都打开投屏画面</p>', '郭娜', '操作错误', '已完成', 1779700204, 1779683824, 1779684359, 26, 26, '', 1779700331, 1779700331);
