INSERT INTO `5kcrm_customer_ledger` VALUES (548, 3, 0, 69, 1, 1, 70, '护士长对绩效功能提出最新要求', '<p>针对护士长提出的关于绩效最新要求，想要在iPad端（或者电脑端）增加一个新的功能；赵晓晓汇总完绩效后上传护理系统，其他人员手动输入工号和密码后查询个人绩效（看不到其他人的绩效）；</p>\n<p>iPad端器械清点增加交接班时间，交班人员自动在交接班时间后延10分钟（例如赵晓晓接邓俞巡回；交接班时间填写为10.30，邓俞确认绩效时时间显示为10.40）</p>', '张婷', '新增需求', '待验证', 1779789203, 1779789203, 0, 26, 2, '', 1779789544, 1784884567);
