INSERT INTO `5kcrm_customer_ledger` VALUES (562, 11, 0, 64, 0, 0, 0, '术中扫码添加器械包，器械包内容物数量翻倍', '<p>从物品清点第一步，术前清点。修改一个物品的数量，例如纱布数量增加一个，然后点下一步，重置一下，然后术前术中在确认一下没有这个包就在进行第三步</p>', '付珊珊', '系统BUG', '已完成', 1780273810, 1780037770, 1780050181, 27, 2, '', 1780274002, 1782186625);
