INSERT INTO `5kcrm_customer_ledger` VALUES (564, 131, 0, 34, 0, 0, 0, '4楼手术室更新IPAD', '<p>更新1-21手术间IPAD&nbsp;</p>', '高存平', '使用指导', '已完成', 1780306354, 1780133554, 1780306426, 3, 3, '', 1780306410, 1780306426);
INSERT INTO `5kcrm_customer_ledger` VALUES (565, 131, 0, 34, 1, 3, 72, '抗生素质控需求，3小时以上手术未再次使用抗生素', '<p>手术时长超过3小时，自首次提交抗生素使用后，没有再次使用抗生素的提示，方便质控。</p>', '高存平', '新增需求', '已完成', 1780306429, 1780306429, 1785496170, 3, 5, '', 1780306545, 1785496170);
INSERT INTO `5kcrm_customer_ledger` VALUES (566, 79, 0, 52, 1, 3, 73, '手术护理记录以视图方式重新提供', '<p>咨询过张工，缺少的信息 以 -&nbsp; 占位即可，无需区分是否为产妇，提供所有手术护理记录。</p>\n<p>表名 主键 外键 主表名 关联主表键<br />EMR_OPERATION_NURSING ID &nbsp;&nbsp;<br />表结构:<br />标识符 名称 数据类型 数据长度 值域代码 填报要求 说明<br />ID 内码 VARCHAR2 100 &nbsp;是 使用组织机构编码+业务主键或流水号<br />ORG_CODE 组织机构代码 VARCHAR2 32 &nbsp;是 医疗机构组织机构代码<br />ORG_NAME 组织机构名称 VARCHAR2 70 &nbsp;是 医疗机构组织机构名称<br />ADMISSION_ID 住院唯一标示号 VARCHAR2 50 &nbsp;是 唯一标示病人某一次住院就诊的标示号<br />DEPT_CODE 科室代码 VARCHAR2 20 CS_SECTION-科室代码- &nbsp; 科室代码<br />DEPT_NAME 科室名称 VARCHAR2 50 &nbsp;是 产妇在医疗机构就诊的科室名称<br />WARD_NAME 病区名称 VARCHAR2 50 &nbsp;是 产妇当前所在病区的名称<br />EORD_NUM 病房号 VARCHAR2 10 &nbsp; 产妇住院期间，所住病房对应的编号<br />SICKBED_NUM 病床号 VARCHAR2 10 &nbsp; 产妇住院期间，所住床位对应的编号<br />OPERATION_ROOM_NUM 手术间编号 VARCHAR2 20 &nbsp; 对患者实施手术操作时所在的手术室房间编号<br />NAME 患者姓名 VARCHAR2 50 &nbsp;是 患者本人在公安户籍管理部门正式登记注册的姓氏和名称<br />SEX_CODE 性别代码 CHAR 1 GBT2261-2003 是 患者生理性别在特定编码体系中的代码<br />SEX_NAME 性别名称 VARCHAR2 50 &nbsp;是 患者生理性别描述<br />AGE 年龄（岁） NUMBER 3 &nbsp;是 0-200<br />AGE_MONTH 年龄（月） VARCHAR2 2 &nbsp; 0-11<br />WEIGHT 体重（kg） NUMBER 6,2 &nbsp;是 患者体重的测量值，计量单位为kg<br />ABO_CODE ABO血型代码 NUMBER 2 CV04.50.005 是 在本次住院期间进行血型检查明确的患者ABO学校类别在特定编码体系中的代码<br />BLOOD_ABO_NAME ABO血型 VARCHAR2 50 &nbsp;是 ABO血型<br />RH_CODE Rh血型代码 NUMBER 2 CC99.00011 是 在本次住院期间进行血型检查明确，或既往病历资料能够明确的患者Rh血型的类别代码<br />BLOOD_RH_NAME RH血型 VARCHAR2 50 &nbsp;是 RH血型<br />DIAGNOSIS_CODE 术前诊断编码 VARCHAR2 12 ICD-10 &nbsp;术前诊断在特定编码体系中的编码<br />DISEASE 疾病诊断名称 VARCHAR2 200 &nbsp;是 根据疾病诊断类型来填疾病名称<br />OPERATION_CODE 手术及操作编码 VARCHAR2 12 ICD-9 &nbsp;患者住院期间实施的手术及操作在特定编码体系中的编码<br />OPERATION_NAME 手术/操作-名称 VARCHAR2 80 &nbsp;是 手术/操作-名称<br />OPERA_DOC_NAME 手术者姓名 VARCHAR2 50 &nbsp;是&nbsp;<br />OPERATION_BP_NAME 手术目标部位名称 VARCHAR2 50 &nbsp;是 实施手术的人体部位名称<br />OPERATION_END_DATE 手术结束日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />OPERATION_START_DATE 手术开始日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />ALLERGIES_CODE 过敏史标志 CHAR 1 1,是 0,否 是 标识患者有无过敏经历的标志<br />ALLERGIES 过敏史 VARCHAR2 1000 &nbsp; 患者既往发生过敏情况的详细描述<br />SKIN_CHECK_NOTE 皮肤检查描述 VARCHAR2 1000 &nbsp; 皮肤检查结果的详细描述<br />NURSE_LEVEL_CODE 护理等级代码 CHAR 1 CV06.00.220 是 护理级别的分类在特定编码体系中的代码<br />NURSE_LEVEL_NAME 护理等级名称 VARCHAR2 50 &nbsp;是 护理级别的分类描述<br />NURSE_OBSERVE_NAME 护理观察项目名称 VARCHAR2 30 &nbsp; 护理观察项目的名称.如患者神志状态、饮食情况、皮肤情况、氧疗情况、排尿排便情 况，流量、出量、入量等等，根据护理内容的 不同选择不同的观察项目名称<br />NURSE_OBSERVE_RESULT 护理观察结果 VARCHAR2 1000 &nbsp;是 对护理观察项目结果的详细描述<br />NURSE_PROJECT 护理操作项目类目名称 VARCHAR2 100 &nbsp;是 多个护理操作项目的名称<br />NURSE_PROJECT_NAME 护理操作名称 VARCHAR2 100 &nbsp;是 进行护理操作的具体名称<br />NURSE_PROJECT_RESULT 护理操作结果 VARCHAR2 1000 &nbsp;是 多个护理操作结果的详细描述<br />IN_ROOM_DATE 入手术室日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />OUT_ROOM_DATE 出手术室日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />PREPARATION 准备事项 VARCHAR2 1000 &nbsp;是 针对病人实施手术的准备工作描述<br />OPERATION_DISEASE_CD 术中病理标志 CHAR 1 1.是 0.否 是 标识术中手术标本是否进行病理切片检查的标志<br />OPERATION_ITEM 术中所用物品名称 VARCHAR2 50 &nbsp;是 术中所用物品的名称<br />BEFORE_OPER_CD 术前清点标志 CHAR 1 1.是 0.否 &nbsp;标识术前是否对即将使用的物品进行清点的标志<br />BEFORE_CHECK_CODE 术前核对标志 CHAR 1 1.是 0.否 &nbsp;标识手术切口缝合前对物品是否进行了清点核对的标志<br />AFTER_CHECK_CODE 术后核对标志 CHAR 1 1.是 0.否 &nbsp;表示手术切口缝合后对物品是否进行了清点核对的标志<br />HANDOVER_PROJECT 病人交接核对项目 VARCHAR2 50 &nbsp;是 病人在进行交接时需要核对的项目名称<br />ROUND_NURSE_NAME 巡台护士签名 VARCHAR2 50 &nbsp; 巡台护士签署的在公安户籍管理部门正式登记注册的姓氏和姓名<br />INS_NURSE_NAME 器械护士签名 VARCHAR2 50 &nbsp; 器械护士签署的在公安户籍管理部门正式登记注册的姓氏和姓名<br />HANDOVER_NURSE 交接护士签名 VARCHAR2 50 &nbsp; 病人交接时，交接护士签署的在公安户籍管理部门正式登记注册的姓氏和名称<br />TRANS_DOC_NAME 转运者签名 VARCHAR2 50 &nbsp; 病人交接时，转运者签署的在公安户籍管理部门正式登记注册的姓氏和姓名<br />HANDOVER_DATE 交接日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />RECORD_DATE 签名日期时间 DATE 15 &nbsp;是 yymmdd hh24miss<br />DISTRICT_CODE 行政区划 VARCHAR2 6 GBT 2260-2007行政区划代码 是 中华人民共和国县级及县级以上<br />行政区划代码<br />EXCHANGE_TYPE 交换类型 VARCHAR2 10 &nbsp;是 INSERT：向平台传新数据时<br />UPDATE：向平台更新某条数据时<br />DELETE：从平台删除某条数据时<br />ADDHIS :向平台补充历史数据<br />SYSTEM_TIME 数据上传时间 TIMESTAMP(6) 6 &nbsp;是 数据上传时间</p>', '张远忠', '新增需求', '已完成', 1780306550, 1780306550, 1780458699, 3, 3, '', 1780306929, 1780458699);
INSERT INTO `5kcrm_customer_ledger` VALUES (567, 131, 0, 34, 0, 0, 0, '病理系统提供新数据', '<p>表本科周主任（庞护士推的微信）要求增加开单医生，但是护理中没有开单医生只有主刀医生，他们要求在视图中增加主刀医生。</p>', '周长春', '三方问题', '已完成', 1780363662, 1780363662, 1780452695, 3, 3, '', 1780363726, 1780452695);
