INSERT INTO `5kcrm_customer_ledger` VALUES (699, 11, 0, 64, 0, 0, 0, '操作日志的时间节点数据化记录', '<p>安全核查、器械清点 等模块的操作和时间节点操作，最后有修改记录，比如时间在XX时间修改过，单据在XX时间修改过 ，修改记录要保留在单据上，那么前提就做好操作日志的时间节点数据化记录。</p>', '黎洋', '新增需求', '已关闭', 1783476210, 1783476210, 0, 3, 5, '', 1783476372, 1784884967);
INSERT INTO `5kcrm_customer_ledger` VALUES (700, 6, 0, 8, 0, 0, 0, '器械清点手动添加器械问题', '<p>器械包缝合6扫码扫不上，手动添加的，平板显示有，但是归档上没有，无纸化也没有<img src=\"https://s.u956.com/public/uploads/20260727/12c786a2f4a8201079539ae5003729c9.png\" /></p>', '张娜', '使用指导', '已完成', 1783488653, 1783483013, 1783484052, 27, 27, '', 1783488802, 1785116353);
INSERT INTO `5kcrm_customer_ledger` VALUES (701, 6, 0, 8, 0, 0, 0, '增加患者感染显示', '<p>王护士长让提取手术通知单界面中的传染性疾病的选项是否勾选 ，0001078094 杨秀芝 胆胰脾外科病&nbsp; 传染性疾病 是选中状态</p>', '王莉', '新增需求', '处理中', 1783495317, 1783495317, 0, 3, 3, '', 1783495385, 1783495495);
