INSERT INTO `5kcrm_customer_ledger` VALUES (703, 11, 0, 64, 1, 1, 80, '增加手术物品清点规范落实率手术安全核查准确执行率', '<p>1、安全核查在每一个步骤完成后，任何变动性操作，包括后台修改时间 就算修改，为当前手术通知单记录修改日志，查询指定通知单存在修改日志的即为安全核查未准确执行，安全核查（质控段）后台修改时间，有选项是否记录修改操作。</p>\n<p>2、器械清点，手术开始清点的时间应该在手术开始（安全核查第二步）之前，如之后属于器械清点规范落实率未达标，如果时修改后的时间需要做对应的提示，标红或可以查询到。</p>\n<p>3、可以查询周期内手术物品清点规范落实率手术安全核查准确执行率，并显示总例数和问题例数，可以点开查看详细的问题手术。</p>', '王兰平', '新增需求', '待发布', 1783501034, 1783501034, 0, 3, 5, '', 1783505063, 1785392715);
