INSERT INTO `5kcrm_customer_ledger` VALUES (731, 79, 0, 52, 0, 0, 0, '术前访视状态显示异常', '<p>1038268&nbsp; B5术间 7月14日 在术前访视中已访视、待访视、已取消中都没有，质控记录中显示是访视中，手工改变type从0到1后状态显示已完成。<br />是 这个患者可能是在保存的时候网络不稳定，导致没有改变访视的状态，现在手工调整是正常（在已访视）的了，我们在观察一下看看是否还存在这样的问题 。</p>', '戚彬厚', '功能完善', '已完成', 1784255739, 1784255739, 1784542562, 3, 3, '', 1784255958, 1784542562);
