INSERT INTO `5kcrm_customer_ledger` VALUES (792, 3, 0, 69, 2, 4, 87, '系统流程故障', '<p>护士长反映系统提醒位置有问题：</p>\n<p>1、交接时就直接提醒低体温/风险评估；跳转填完后会忘记填写交接；护士长希望将风险评估提醒改到安全核查第一步；低体温评估改到器械清点第一步</p>\n<p>2、安全核查第三步患者离开手术室前护士签名后会同步给离室时间，护士长希望不再进行同步</p>', '张婷', '系统BUG', '待处理', 1785318583, 1785318583, 0, 26, 2, '', 1785318820, 1785318820);
