INSERT INTO `5kcrm_customer_ledger` VALUES (794, 11, 0, 64, 0, 0, 0, '追溯模块器械包回传失败', '<p>310手术间597004王合龙，追溯模块，回传CSSD 显示缺少手术或清点单参数</p>\n<p><img src=\"https://s.u956.com/public/uploads/20260730/77a19a72ed364b4d4b3d68a8a4c3e192.png\" /></p>', '徐红霞', '使用指导', '已完成', 1785378794, 1785377354, 1785377683, 27, 27, '', 1785379423, 1785389529);
