DROP TABLE IF EXISTS `5kcrm_customer_ledger`;
CREATE TABLE `5kcrm_customer_ledger`  (
  `ledger_id` int(11) NOT NULL AUTO_INCREMENT,
  `customer_id` int(11) NOT NULL DEFAULT 0 COMMENT '客户ID',
  `business_id` int(11) NOT NULL DEFAULT 0 COMMENT '商机ID',
  `contract_id` int(11) NOT NULL DEFAULT 0 COMMENT '合同ID',
  `work_id` int(11) NOT NULL DEFAULT 0 COMMENT '项目ID',
  `class_id` int(11) NOT NULL DEFAULT 0 COMMENT '任务列表ID',
  `task_id` int(11) NOT NULL DEFAULT 0 COMMENT '项目任务ID',
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '反馈问题',
  `description` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '问题描述',
  `feedback_user` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '反馈人',
  `category` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '问题分类',
  `status` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '' COMMENT '处理状态',
  `register_time` int(11) NOT NULL DEFAULT 0 COMMENT '登记时间',
  `feedback_time` int(11) NOT NULL DEFAULT 0 COMMENT '反馈时间',
  `finish_time` int(11) NOT NULL DEFAULT 0 COMMENT '处理完成时间',
  `register_user_id` int(11) NOT NULL DEFAULT 0 COMMENT '登记人',
