  PRIMARY KEY (`ledger_id`) USING BTREE,
  INDEX `idx_ledger_customer`(`customer_id`) USING BTREE,
  INDEX `idx_ledger_status`(`status`) USING BTREE,
  INDEX `idx_ledger_category`(`category`) USING BTREE,
  INDEX `idx_ledger_business`(`business_id`) USING BTREE,
  INDEX `idx_ledger_contract`(`contract_id`) USING BTREE,
  INDEX `idx_ledger_task`(`task_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 807 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '客户台账' ROW_FORMAT = Dynamic;

